questionvariables.text:
/* Part (a) randomisation */
angleA:rand_with_prohib(12,20,[18])*5;
radA:rand(8)+2;

/* Pard (b) randomisation */
radB1:rand_with_prohib(5,19,[10])/10;
radB2:rand_with_prohib(10*radB1+5,29,[10,20])/10;
heightB:rand_with_step(ceiling(5*radB1), floor(5*sqrt(3)*radB1), 1)/10;

/* Solutions */
tans1:(angleA/360)*%pi*radA^2;

tans2:(1/2)*radA^2*sin(angleA*(%pi/180));

tans3:tans1-tans2;

angB1:2*asin(heightB/(2*radB1));
angB2:2*asin(heightB/(2*radB2));

tans4:(1/2)*(angB1 - sin(angB1))*radB1^2 + (1/2)*(angB2 - sin(angB2))*radB2^2;

tans5:radB1*angB1 + radB2*angB2;

feedbackvariables.text:
/* Node 1: Correct answer */
/* Node 2: Worked solution */

/* Node 3: Correct answer but incorrect rounding (1) */
node3_test: if abs(ans1-tans1) <= 1 then 1 else 0;

/* Node 4: No attempt to use sector angle */
node4_test: if abs(ans1-(pi*radA^2)) <= 1 then 1 else 0;

/* Node 1: Correct answer */
/* Node 2: Worked solution */

/* Node 3: Correct answer but incorrect rounding (1) */
node3_test: if abs(ans2-tans2) <=1 then 1 else 0;

/* Node 1: Correct answer (allow error from intermediate rounding) */
node1_test: if ans3=significantfigures(tans3,3) or ans3=significantfigures(tans2,3)-significantfigures(tans1,3) then 1 else 0;

/* Node 2: Worked solution */

/* Node 3: Ecf (1) */
node3_test: if ans3=significantfigures(ans2-ans1,3) or ans3=significantfigures(ans2,3)-significantfigures(ans1,3) then 1 else 0;

/* Node 1: Correct area */
/* Node 2: Worked solution */
/* Node 3: Correct area, incorrectly rounded */
node3_test: if abs(ans4-tans4) <= 1 then 1 else 0;

/* Node 4: Correct perimeter */
/* Node 5: Correct perimeter, incorrectly rounded */
node5_test: if abs(ans5-tans5) <= 1 then 1 else 0;
